insert into public.questions (company, topic, question, answer, example, access_level, is_free) values
('React', 'React Machine Coding', 'Build an accessible accordion with single-open and multi-open modes.', 'Model the expanded panel IDs as a Set so either mode can be supported. In single-open mode, replace the Set with the selected ID. Use buttons with aria-expanded and aria-controls, stable panel IDs, keyboard activation, and semantic headings. Keep the content mounted or unmounted intentionally; if it is unmounted, preserve state only when the requirements call for it.', 'Verify the initial state, toggling one panel, opening a second panel in each mode, keyboard operation, and that each button announces the correct expanded state.', null, true),
('React', 'React Machine Coding', 'Build a searchable autocomplete that supports keyboard selection.', 'Keep the query, open state, active option index, and selected value separate. Filter a stable option list, debounce remote requests when applicable, cancel or ignore stale responses, and implement ArrowUp/ArrowDown, Enter, Escape, and click selection. Connect the input and listbox with ARIA roles and active-descendant semantics.', 'Type a partial term, move through results with arrows, select with Enter, dismiss with Escape, and confirm a late response cannot replace newer results.', null, true),
('React', 'React Machine Coding', 'Build a star-rating component with hover preview and a read-only mode.', 'Keep the committed rating separate from the transient hover rating. Render each star as a button with an accessible label, support keyboard focus and selection, and disable interaction in read-only mode. Define whether half-star selection is in scope before implementing it.', 'Rate 4 stars, hover over 2 without changing the saved value, move the pointer away to restore 4, then verify read-only ratings cannot be changed.', null, true),
('React', 'React Machine Coding', 'Build a tabs component with accessible keyboard navigation.', 'Represent each tab with a stable ID and selected state. Use tablist, tab, and tabpanel roles with matching aria-controls and aria-labelledby. Support Left/Right arrows, Home/End, and either automatic or manual activation; choose based on panel loading cost and document the choice.', 'Verify only one tab is selected, arrow keys move focus, activation changes the panel, and focus remains predictable when a tab is disabled.', null, true),
('React', 'React Machine Coding', 'Build a modal dialog with focus management and dismissal rules.', 'Render the dialog in a portal, move focus into it on open, keep keyboard focus inside, close on Escape when allowed, and restore focus to the opener. Add an accessible name, inert or otherwise non-interactive background, and deliberate backdrop-click behavior. Clean up all listeners on unmount.', 'Open from a button, tab through the dialog without reaching the page behind it, dismiss with Escape, and confirm focus returns to the opener.', null, true),
('React', 'React Machine Coding', 'Build a toast notification system with timed dismissal.', 'Keep notifications in a centralized queue with stable IDs and explicit variants. Use one timer per toast and clear timers on dismissal and unmount. Avoid stealing focus for routine updates; provide an appropriate live region and pause or extend dismissal while the user hovers or focuses the toast.', 'Show two notifications, dismiss one manually, wait for the other to expire, and verify a focused toast is not removed unexpectedly.', null, true),
('React', 'React Machine Coding', 'Build a paginated data table with sorting and empty/loading states.', 'Keep sort key, direction, current page, and page size explicit. Use stable row IDs and derive sorted and paginated rows rather than mutating source data. Reset or clamp the page when filters or page size change. Expose sort state to assistive technology and provide loading, empty, and error states.', 'Sort a column in both directions, move between pages, change page size on the last page, and verify an empty result has a clear message.', null, true),
('React', 'React Machine Coding', 'Build a progress bar that supports determinate and indeterminate work.', 'For determinate progress, validate and clamp the value to the range, expose progressbar semantics and value text, and avoid announcing every tiny change excessively. For unknown progress, use an indeterminate visual and omit aria-valuenow. Respect reduced-motion preferences.', 'Test zero, partial, complete, out-of-range values, and an indeterminate state with a useful accessible label.', null, true),
('React', 'React Machine Coding', 'Build a debounced search box that ignores stale results.', 'Separate raw input from the debounced query. Debounce only the request trigger, cancel prior requests with AbortController when supported, and still guard responses with a request sequence in case cancellation is ignored. Represent loading, error, empty, and success states distinctly.', 'Search for two terms quickly while delaying the first response; confirm only results for the latest term are shown and the timer is cleaned up.', null, true),
('React', 'React Machine Coding', 'Build a tic-tac-toe game with turn tracking and win detection.', 'Store the board as an immutable nine-cell array and derive the next player, winner, and draw state from it. Define winning lines once, reject moves on occupied cells or after completion, and keep reset behavior explicit. Separate pure game logic from rendering so it can be tested independently.', 'Play a win, a draw, an occupied-cell attempt, and reset; verify the winner and next-player message are correct.', null, true),
('React', 'React Machine Coding', 'Build a nested comment thread with replies and deletion.', 'Model comments by ID with parent IDs and stable ordering, or use a normalized tree if edits and cross-references are needed. Keep reply drafts local to each form, validate empty submissions, and define delete behavior for a comment with descendants. Render the hierarchy semantically and avoid using array indexes as keys.', 'Reply at two depths, cancel a draft, delete a parent with replies according to the chosen policy, and verify sibling order remains stable.', null, false),
('React', 'React Machine Coding', 'Build a shopping cart with quantity controls, totals, and persisted state.', 'Keep cart lines normalized by product ID and derive subtotal, discounts, tax, and total rather than storing duplicated totals. Validate quantity bounds, handle removed or changed catalog items, and use integer minor currency units to avoid floating-point money errors. Persist versioned cart state and guard storage parsing.', 'Add two products, change quantity, remove one, reload persisted state, and verify rounded totals with a fractional tax rate.', null, false),
('React', 'React Machine Coding', 'Build a drag-and-drop Kanban board with keyboard alternatives.', 'Represent columns and cards with stable IDs and derive ordering from column membership and position. Update state immutably, support moving across and within columns, and provide keyboard controls or move menus so drag is not the only interaction. Persist only a versioned board model and handle invalid drop targets.', 'Move a card within a column and to another column, undo a rejected drop, reorder columns, and complete the same move using the keyboard.', null, false),
('React', 'React Machine Coding', 'Build a monthly calendar with event creation and editing.', 'Represent dates in a consistent local-date or UTC model and document timezone behavior. Derive the visible month grid, keep events keyed by stable IDs and date, and support month navigation without mutating Date objects. Make event creation/edit forms accessible and define how events crossing midnight are displayed.', 'Navigate across a year boundary, add an event on a month-padding day, edit it, and verify daylight-saving dates remain on the intended calendar day.', null, false),
('React', 'React Machine Coding', 'Build a file explorer tree with expandable folders and selection.', 'Use a normalized tree or recursive node model with stable IDs. Track expanded folders and selected node IDs separately, support keyboard navigation and ARIA tree patterns, and avoid recursively rendering inaccessible or huge trees without virtualization. Define behavior for selecting a folder versus opening it.', 'Expand nested folders, navigate with arrow keys, select a file, collapse its ancestor, and confirm selection behavior is deliberate.', null, false),
('React', 'React Machine Coding', 'Build a multi-step form with validation and draft recovery.', 'Define steps and field schemas explicitly. Validate at the appropriate boundary, preserve values when navigating backward, focus the first invalid field, and prevent duplicate submission. Persist only safe draft data with a schema version and clear it after successful completion; do not store secrets in local storage.', 'Complete a step, go back and edit it, reload a recoverable draft, submit invalid data, and verify the error summary and field focus.', null, false),
('React', 'React Machine Coding', 'Build a transfer list with search and bulk selection.', 'Maintain selected IDs as sets on each side and derive visible filtered items. Bulk-select should affect only the currently visible eligible items, not silently override hidden selections. Move operations should preserve stable ordering and handle duplicate IDs defensively.', 'Select visible items under a filter, bulk-select, change the filter, move selected items, and verify hidden selections follow the documented rule.', null, false),
('React', 'React Machine Coding', 'Build infinite scrolling with a loading sentinel and duplicate prevention.', 'Use IntersectionObserver with a cleanup path and a guarded load-more function. Track cursor, loading, has-more, and error states; deduplicate records by stable ID and protect against overlapping requests. Provide a manual load-more fallback and consider virtualization for long lists.', 'Scroll to trigger multiple pages, simulate an overlapping observer callback, retry a failed page, and verify there are no duplicate items or requests after unmount.', null, false),
('React', 'React Machine Coding', 'Build an undo/redo history for a small editor.', 'Represent history as past, present, and future snapshots or reversible operations. Commit only meaningful changes, clear the redo stack after a new edit, and impose an explicit memory/history limit. Keep updates immutable and define how grouped typing becomes one undo step.', 'Type multiple characters, undo twice, redo once, make a new edit, and verify the previous redo history is discarded.', null, false),
('React', 'React Machine Coding', 'Build an OTP input with paste, auto-advance, and accessible errors.', 'Store the complete code as a string and treat individual boxes as a visual input model. Handle digit entry, paste, Backspace, arrows, and focus movement without breaking screen-reader labeling. Validate length and submission state, avoid logging the OTP, and clear timers or requests on unmount.', 'Enter digits, paste a full code, correct a middle digit, submit a wrong code, and verify focus and error announcement are useful.', null, false),
('React', 'React Machine Coding', 'Build a reusable tree-select for hierarchical categories.', 'Track selected IDs independently from expanded nodes and define whether selecting a parent selects descendants. Derive indeterminate states from children rather than storing them. Implement tree keyboard navigation, accessible labels, and clear behavior when a selected node is removed or filtered out.', 'Select one leaf, then a parent, inspect indeterminate states, collapse the tree, and verify keyboard navigation still reaches selected nodes.', null, false),
('React', 'React Machine Coding', 'Build an image carousel with controls, autoplay, and reduced motion.', 'Use a controlled active index with wraparound rules, accessible previous/next controls, and a label that conveys position. Autoplay should pause on hover/focus and when the page is hidden, obey reduced-motion preferences, and clean up its interval. Avoid announcing every autoplay tick aggressively.', 'Navigate at both ends, pause autoplay on focus, switch tabs, and test reduced-motion mode and a single-image carousel.', null, false),
('React', 'React Machine Coding', 'Build a stopwatch with start, pause, lap, and reset.', 'Use a monotonic clock such as performance.now() and derive elapsed time from a start timestamp plus accumulated duration, rather than incrementing a counter each interval. Keep interval ticks for rendering only, clean them up on pause/unmount, and format laps from captured timestamps.', 'Start, record laps, pause, resume, and reset; verify elapsed time does not drift significantly when the tab is throttled.', null, false),
('React', 'React Machine Coding', 'Build a quiz flow with timed questions and a result summary.', 'Separate question data from answer state, record answers by stable question ID, and derive score from the answer key. Use a single deadline timestamp for timing rather than decrementing state as the source of truth. Handle timeout, back navigation policy, restart, and keyboard-accessible choices.', 'Answer, skip, revisit if allowed, expire the timer, restart, and verify scoring ignores unanswered questions correctly.', null, false),
('React', 'React Machine Coding', 'Build a reusable form builder from a field schema.', 'Define a typed schema with stable field IDs, supported control types, validators, and conditional visibility rules. Render controls through a registry, keep values separate from schema, and validate both visible and hidden fields according to documented policy. Avoid evaluating arbitrary expressions from the schema.', 'Render text, select, and checkbox fields, hide a conditional field, submit invalid values, and confirm schema validation reports field-specific messages.', null, false),
('React', 'React Machine Coding', 'Build a markdown preview with safe rendering and debounced updates.', 'Keep source text as the canonical state and derive the preview with a bounded debounce if parsing is expensive. Sanitize generated HTML or use a renderer that escapes raw HTML by default; never inject untrusted markup unsanitized. Support empty, large-input, and parse-error states.', 'Render headings and links, include an attempted script tag, and confirm it is displayed safely rather than executed.', null, false),
('React', 'React Machine Coding', 'Build a dependent country, region, and city selector.', 'Represent dependencies explicitly and clear downstream values immediately when an upstream selection changes. Cancel or ignore stale option requests, expose loading/empty/error states per selector, and prevent submission while the selected chain is invalid.', 'Choose a country and region, change country while regions are loading, and verify stale cities and responses cannot remain selected.', null, false),
('React', 'React Machine Coding', 'Build a notification center with unread state and bulk actions.', 'Normalize notifications by ID and derive unread count. Keep read state and dismissal separate, support mark-all-read atomically, and use pagination or virtualization for large histories. Announce new items appropriately without repeatedly reading the entire list.', 'Add notifications, mark one and all as read, dismiss an item, and verify unread count and empty state stay consistent.', null, false),
('React', 'React Machine Coding', 'Build a reusable data grid with filtering, sorting, and column visibility.', 'Keep grid state explicit and derive rows through a predictable pipeline: filter, sort, then paginate. Use stable row and column IDs, distinguish client-side from server-side modes, and expose sort/filter state accessibly. For large data, virtualize rows while preserving keyboard navigation and focus.', 'Combine a filter and sort, hide a column, move to another page, and verify the result count, visible headers, and focus behavior are correct.', null, false),
('React', 'React Machine Coding', 'Build an async image uploader with previews and retry.', 'Track each upload by ID with explicit queued, uploading, succeeded, failed, and canceled states. Validate size and type before upload, revoke object URLs when previews are removed or the component unmounts, and support cancellation and retry without duplicate records. Keep server-side validation authoritative.', 'Upload two files, cancel one, retry a failed one, remove a preview, and verify object URLs and in-flight requests are cleaned up.', null, false)
